-- V2 slice 3 (ticket 03): zip + radius discovery.
--
-- Pinned contracts (plan-v2.md Interfaces):
-- - zip_codes: zip (pk), lat, lng — seeded gazetteer extract
-- - profiles: + home_zip (text, nullable), + radius_miles (int, not null,
--   default 5, CHECK between 2 and 35)
-- - Radius pin: haversine in plain SQL, NO PostGIS; the distance predicate
--   also exists as a pure function in src/lib/feed.ts (unit-tested) and the
--   feed query runs it client-side over a pinned-embed fetch (PGRST201:
--   every embed carries its FK hint).
--
-- Seed provenance: SimpleMaps US ZIP Codes Basic v1.95.1 (CC-BY-4.0,
-- free tier; zip/lat/lng per zip, one row per zip), filtered to
-- state_id = WA — 605 rows (every active WA USPS zip: 980xx–989xx +
-- 990xx–994xx; well under the 3K-row flag). Source:
-- https://simplemaps.com/data/us-zips
--
-- Idempotent + re-paste-safe (house pattern, 2026-09-04 lesson): the table
-- via IF NOT EXISTS; RLS is ON by re-running; the policy + the constraint
-- + the owner UPDATE policy in DO blocks; the seed via
-- ON CONFLICT (zip) DO NOTHING.

-- 1) zip_codes: the seeded gazetteer (zip -> lat/lng). Authenticated read
-- only — there is no user write policy (RLS denies by default), so the
-- seed is only ever (re)written by service_role (the CDP apply).
create table if not exists public.zip_codes (
  zip text primary key,
  lat numeric not null,
  lng numeric not null
);

alter table public.zip_codes enable row level security;

on conflict (zip) do nothing;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public'
      and tablename = 'zip_codes'
      and policyname = 'zip_codes_select_authenticated'
  ) then
    create policy "zip_codes_select_authenticated"
      on public.zip_codes for select
      to authenticated
      using (true);
  end if;
end
$$;

-- 2) profiles: home_zip + radius_miles (the radius options 2/5/10/20/35
-- are app-enforced (feed.ts RADIUS_MILES_OPTIONS); the CHECK 2–35 is the
-- DB backstop, per the pinned data model).
do $$
begin
  alter table public.profiles add column if not exists home_zip text;
  alter table public.profiles add column if not exists radius_miles integer not null default 5;
end
$$;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_radius_miles_chk'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint "profiles_radius_miles_chk" check (radius_miles between 2 and 35);
  end if;
end
$$;

-- 3) Owner-scoped UPDATE for the location columns. 0001's
-- profiles_update_own already grants owner updates on every column; this
-- policy makes the new columns' owner scoping explicit (additive and
-- permissive — union semantics make it a documented no-op delta, re-
-- paste-safe via the DO-block guard).
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public'
      and tablename = 'profiles'
      and policyname = 'profiles_update_location_own'
  ) then
    create policy "profiles_update_location_own"
      on public.profiles for update
      to authenticated
      using (auth.uid() = id)
      with check (auth.uid() = id);
  end if;
end
$$;
